(()=>{const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const topics={
overview:['Visão gerencial','Entenda o que aconteceu com as áreas ofertadas antes de formar uma nova carteira.',['Escolha um recorte mineral ou clique em uma rodada, resultado ou estado. Os indicadores e gráficos desta página usam a mesma seleção.','Clique novamente na categoria para retirar o filtro, ou use Limpar seleção. Examine essas áreas leva o recorte para o explorador.','As colunas mostram lances por rodada; a linha soma os valores do recorte. A 6ª e a 7ª aparecem com contribuição financeira zero por regras diferentes, não por valor econômico nulo.'],'Use os padrões para formular perguntas à equipe. Lances registrados não comprovam receita recebida; a presença de uma substância não comprova reserva.'],
models:['Evidências dos modelos','Confira se a complexidade do algoritmo acrescenta informação útil.',['Leia primeiro o exemplo em quantidade de áreas: capacidade de revisão, casos encontrados e referência com a mesma capacidade.','F1 macro equilibra os três destinos; não é a porcentagem de áreas que o gestor deveria ofertar. A matriz mostra também onde o modelo erra.','Confira as diferenças entre o conjunto geral e os recortes minerais. A vantagem pode desaparecer em um subgrupo.'],'O teste é retrospectivo. A proposta é um piloto de triagem com analistas, não uma escolha automática da próxima rodada.'],
simulation:['Simular uma seleção','Teste uma capacidade de revisão usando resultados históricos conhecidos.',['Escolha arrematação, conquista ou área livre e delimite o recorte.','Mova a capacidade da equipe; compare a precisão do modelo com a referência por estado.','A lista mostra a seleção histórica. Ordene colunas, busque processos e exporte para conferir os casos.'],'As pontuações não são probabilidades calibradas do estoque atual. Não use o simulador para orçamento ou preço mínimo.'],
journey:['Depois do leilão','Escolha processos para acompanhar sua evolução administrativa e arrecadatória.',['Selecione rodada e grupo mineral; observe quantos processos tiveram vínculos encontrados.','Os marcos se sobrepõem: alvará, relatório aprovado e guia podem pertencer ao mesmo processo. Não some os cartões como etapas exclusivas.','Carregue os processos e abra uma ficha para ver a ligação entre origem e associado, eventos e CFEM por ano.'],'O início é a associação, não uma data de arrematação presumida. Ausência de registro não prova inatividade. Produção individual, licenciamento e PLG ainda não estão completamente consolidados.'],
planning:['Planejar uma carteira','Prepare uma lista de áreas aptas para revisão técnica antes de uma próxima rodada.',['Filtre o retrato do estoque por substância, UF e processo. Todas as linhas foram classificadas como aptas na fonte da data indicada.','Marque processos para revisão. As marcações permanecem ao trocar filtros, somente durante esta visita.','Exporte a lista para a equipe. A ordenação por área é apenas descritiva, sem pontuação preditiva.'],'Aptidão não garante inclusão em edital. Antes de usar IA no estoque, confira restrições, atributos na data da decisão e diferenças em relação às áreas já ofertadas. A fila preditiva prospectiva ainda não foi validada.'],
explore:['Explorar áreas','Investigue os processos que compõem um padrão observado no painel.',['Combine rodada, UF, município, processo, substância e resultado. Os filtros são cumulativos.','Clique em uma coluna de rodada ou em um resultado para filtrar os gráficos, indicadores, mapa e tabela da exploração.','Abra a ficha da área para conferir eventos e poligonal. As colunas da tabela permitem ordenação; a busca aceita 000.000/0000.'],'Os registros são ocorrências por rodada, não terrenos únicos. A geometria atual pode ser diferente da poligonal do edital.'],
stock:['Estoque atual','Veja como os processos estão classificados no retrato do estoque.',['Selecione UF, situação e texto livre.','Separe aptas, em análise, para análise e não aptas.','Para montar uma lista de revisão apenas das aptas, use Planejar uma carteira no menu principal.'],'A situação é da coleta informada. A base não demonstra sozinha quanto tempo cada processo aguardou nem certifica aptidão atual.'],
profiles:['Perfis das áreas','Compare carteiras com características semelhantes.',['Observe substâncias, tamanho, localização e regime no mesmo recorte.','Nos agrupamentos V4, compare idade e densidade do histórico entre perfis.','Use os grupos para preparar perguntas e distribuir revisões por tipo de histórico.'],'Agrupamento não significa depósito geológico, causa de desinteresse ou gargalo confirmado. Uma área pode ter várias substâncias.'],
method:['Método, fontes e atualização','Confira o que foi medido, quando e com quais limites.',['A data de coleta identifica o retrato dos dados; atualização da interface é a publicação deste produto.','Baixe o protocolo, código e resultados para reproduzir os experimentos.','O navegador pode detectar um novo manifesto publicado. A conexão automática de dados às fontes será uma etapa futura.'],'Atualizar a interface não atualiza silenciosamente modelos nem bases. Mudanças de fonte e novas rodadas exigem revisão.'],
legacy:['Experimentos anteriores','Entenda a evolução do estudo sem confundir versões.',['Esta página conserva resultados históricos da versão indicada.','Leia as interpretações ao lado das métricas e compare com as regras simples.','Consulte Evidências dos modelos no menu para a avaliação V5.'],'Um resultado antigo não foi substituído por um novo sem registro. Não combine métricas de alvos diferentes como se fossem comparáveis.']};
const header=document.querySelector('.topbar');if(!header)return;const full=header.querySelector('button'),button=document.createElement('button');button.className='button header-guide';button.type='button';button.textContent='✦ Guia passo a passo';button.setAttribute('aria-haspopup','dialog');full.after(button);
const stamp=document.createElement('div');stamp.className='data-stamp';stamp.setAttribute('role','status');stamp.textContent='Consultando datas de coleta e atualização…';header.after(stamp);
const dialog=document.createElement('dialog');dialog.className='guide-dialog';dialog.innerHTML='<button class="button" data-close>Fechar ×</button><h2 id="guide-dialog-title">Guia de uso</h2><nav aria-label="Escolher guia"></nav><div class="guide-content"></div>';dialog.setAttribute('aria-labelledby','guide-dialog-title');document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let metadata;function current(){if(location.pathname.includes('utilidade'))return 'legacy';const v=document.querySelector('.view:not([hidden])')?.id;return topics[v]?v:'method'}
function show(key){const t=topics[key]||topics.method;dialog.querySelector('h2').textContent=t[0];dialog.querySelector('nav').innerHTML=Object.entries(topics).map(([k,v])=>`<button data-topic="${k}" aria-pressed="${k===key}">${escape(v[0])}</button>`).join('');dialog.querySelector('.guide-content').innerHTML=`<p><b>Para que serve:</b> ${escape(t[1])}</p><h3>Faça em três passos</h3><ol>${t[2].map(x=>'<li>'+escape(x)+'</li>').join('')}</ol><p class="notice"><b>Como interpretar:</b> ${escape(t[3])}</p>`+'<h3>Quem usa e qual decisão pode apoiar?</h3><p><b>ANM:</b> comparar áreas e preparar uma carteira para revisão técnica, conferir pendências e acompanhar processos depois do leilão.</p><p><b>Minerador:</b> localizar oportunidades compatíveis com sua estratégia e escolher quais áreas estudar com mais profundidade. Os lances passados são contexto, não uma recomendação de preço.</p><p><b>Setor e sociedade:</b> acompanhar resultados e a trajetória das áreas com transparência. O painel não é um serviço oficial da ANM.</p>'+(key==='method'&&metadata?'<h3>Datas das fontes preservadas</h3><div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Coleta registrada</th><th>Última modificação informada</th></tr></thead><tbody>'+metadata.sources.map(r=>`<tr><td>${escape(r.file)}</td><td>${escape(r.extracted_at||'Não registrada')}</td><td>${escape(r.last_modified||'Não informada')}</td></tr>`).join('')+'</tbody></table></div>':'');}
button.onclick=()=>{show(current());dialog.showModal()};dialog.querySelector('nav').onclick=e=>{if(e.target.dataset.topic)show(e.target.dataset.topic)};
async function refresh(){try{const r=await fetch('data-status.json',{cache:'no-cache'});if(!r.ok)throw Error();const next=await r.json();if(metadata&&metadata.version!==next.version){stamp.innerHTML='Há uma nova versão publicada. <button class="button" id="data-refresh">Recarregar painel</button>';stamp.querySelector('button').onclick=()=>location.reload();return}metadata=next;const date=new Date(next.interface_updated_at).toLocaleDateString('pt-BR');stamp.textContent=`Coleta da base: ${next.data_collected_at.split('-').reverse().join('/')} · Interface atualizada: ${date} · CFEM acompanhada até 2025 · Conexão em tempo real ainda não ativa.`}catch(e){stamp.textContent='Datas de atualização indisponíveis. Consulte Método e dados antes de interpretar a atualidade da base.'}}
refresh();setInterval(()=>{if(!document.hidden)refresh()},300000);
})();
